CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS products(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),external_id TEXT NOT NULL,source TEXT NOT NULL,title TEXT NOT NULL,description TEXT,currency CHAR(3) NOT NULL,cost NUMERIC(14,2) NOT NULL CHECK(cost>=0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source,external_id));
CREATE TABLE IF NOT EXISTS orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),status TEXT NOT NULL DEFAULT 'pending_payment',currency CHAR(3) NOT NULL,subtotal NUMERIC(14,2) NOT NULL CHECK(subtotal>=0),shipping NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(shipping>=0),total NUMERIC(14,2) NOT NULL CHECK(total>=0),payment_provider TEXT,external_payment_id TEXT,fulfillment_provider TEXT,external_fulfillment_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),type TEXT NOT NULL,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL DEFAULT now(),locked_at TIMESTAMPTZ,last_error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_ready_idx ON jobs(status,available_at);
CREATE TABLE IF NOT EXISTS idempotency_keys(key TEXT PRIMARY KEY,request_hash TEXT NOT NULL,response_status INTEGER NOT NULL,response_body JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,risk TEXT NOT NULL,evidence JSONB NOT NULL DEFAULT '[]',metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
